  required JsAppInfo app,
  required ExecutionEnv env,
  required AppPermissions permissions,
  String entryFile = JsAppEngine.defaultEntryFile,
  void Function(JsAppErrorEvent event)? errorSink,
}) => JsAppEngine(
  app: app,
  env: env,
  permissions: permissions,
  entryFile: entryFile,
  errorSink: errorSink,
